#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

// Structure to hold a rule
typedef struct {
    char src_ip[50];
    char dst_ip[50];
    int src_port;
    int dst_port;
} Rule;

// Function to load the ruleset from file
void load_rules(Rule** rules, int* num_rules) {
    FILE *fp = fopen("rules.txt", "r");
    if (fp == NULL) {
        printf("Error loading rules\n");
        return;
    }

    char line[1024];
    while (fgets(line, 1024, fp)) {
        Rule* rule = malloc(sizeof(Rule));
        sscanf(line, "%s %s %d %d", rule->src_ip, rule->dst_ip, &rule->src_port, &rule->dst_port);
        (*num_rules)++;
        (*rules) = realloc((*rules), sizeof(Rule*) * (*num_rules));
        (*rules)[(*num_rules) - 1] = rule;
    }
    fclose(fp);
}

// Function to check if a packet matches any of the rules
int check_rule(Packet* packet, Rule** rules, int num_rules) {
    for (int i = 0; i < num_rules; i++) {
        if ((strcmp(packet->src_ip, rules[i]->src_ip) == 0) &&
            (strcmp(packet->dst_ip, rules[i]->dst_ip) == 0) &&
            (packet->src_port == rules[i]->src_port) &&
            (packet->dst_port == rules[i]->dst_port)) {
            return 1;
        }
    }
    return 0;
}

