int main() {
    Rule** rules = NULL;
    int num_rules = 0;

    load_rules(&rules, &num_rules);

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket error");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(1234);

    if (bind(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind error");
        return -1;
    }

    char buffer[BUFFER_SIZE];
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int bytes_received;

    while (1) {
        bytes_received = recvfrom(sock, buffer, BUFFER_SIZE, 0, (struct sockaddr*)&client_addr, &client_len);

        if (bytes_received < 0) {
            perror("recvfrom error");
            return -1;
        }

        Packet* packet = malloc(sizeof(Packet));
        packet->src_ip = inet_ntoa(client_addr.sin_addr);
        packet->dst_ip = "127.0.0.1";
        packet->src_port = ntohs(client_addr.sin_port);
        packet->dst_port = 1234;

        int rule_match = check_rule(packet, rules, num_rules);

        if (rule_match) {
            printf("Rule match detected\n");
            close(sock);
            return 0;
        } else {
            update_rules(&rules, &num_rules, packet);
        }

        free(packet);
    }

    return 0;
}

